/*
 * Costa's Meat Market — "Open now / Closed now" badge for the hours table, using Florida time.
 * The page provides the schedule and labels in data-open-now (generated by _build/lib/home.py).
 */
(function () {
  var badge = document.querySelector("[data-open-now]");
  if (!badge || !window.Intl) return;
  var cfg;
  try { cfg = JSON.parse(badge.getAttribute("data-open-now")); } catch (e) { return; }

  var parts = {};
  new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York", weekday: "short", hour: "numeric", minute: "numeric", hour12: false
  }).formatToParts(new Date()).forEach(function (p) { parts[p.type] = p.value; });

  var day = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].indexOf(parts.weekday);
  if (day < 0) return;
  var now = (parseInt(parts.hour, 10) % 24) + parseInt(parts.minute, 10) / 60;
  var today = cfg.hours[day];
  var open = now >= today[0] && now < today[1];
  var next = now < today[0] ? today : cfg.hours[(day + 1) % 7];

  badge.textContent = open
    ? cfg.open + " · " + cfg.closes.replace("{t}", cfg.t[today[1]])
    : cfg.closed + " · " + cfg.opens.replace("{t}", cfg.t[next[0]]);
  badge.className += open ? " is-open" : " is-closed";
  badge.hidden = false;

  var row = document.querySelector('[data-day="' + day + '"]');
  if (row) row.className += " today";
})();
